        agent_action.is_unlocked = False
    if not hasattr(agent_action, 'unlock_steps'):
        agent_action.unlock_steps = 0
    if not hasattr(agent_action, 'exit_steps'):
        agent_action.exit_steps = 0

    is_unlocked = agent_action.is_unlocked
    unlock_steps = agent_action.unlock_steps
    exit_steps = agent_action.exit_steps

    # Check if in unlock zone
    in_unlock = 5.0 <= x <= 10.0

    # Unlock phase
    if not is_unlocked:
        if in_unlock:
            # Check if speed is below 100 m/s
            if abs(vx) < 100:
                # Apply force to trigger unlock (Fx < -34 N)
                sandbox.apply_agent_force(-35, 0)
                unlock_steps += 1
                if unlock_steps >= 5:
                    is_unlocked = True
                    unlock_steps = 0
            else:
                unlock_steps = 0
        else:
            # Navigation phase: use whiskers to avoid walls
            if front < 3.0:
                # Wall in front, check up/down whiskers
                if up < 3.0:
                    # Wall above, move down
                    sandbox.apply_agent_force(0, -5)
                elif down < 3.0:
                    # Wall below, move up
                    sandbox.apply_agent_force(0, 5)
                else:
                    # No up/down wall, turn left/right based on whiskers
                    if up < 3.0:
                        # Turn right
                        sandbox.apply_agent_force(5, 0)
                    elif down < 3.0:
                        # Turn left
                        sandbox.apply_agent_force(-5, 0)
            else:
                # Move forward
                sandbox.apply_agent_force(5, 0)
    else:
        # Post-unlock phase: navigate to exit zone
        if x >= 15.0 and 0.5 <= y <= 2.5:
            exit_steps += 1
            if exit_steps >= 5:
                # Task complete: hold in exit zone
                pass
        else:
            # Move forward
            sandbox.apply_agent_force(5, 0)

    # Update global variables
    agent_action.is_unlocked = is_unlocked
    agent_action.unlock_steps = unlock_steps
    agent_action.exit_steps = exit_steps
